// === Tab: mySketch ===
let theShader = null;

function preload() {
	theShader = createShader(vert, frag);
}

function setup() {
	createCanvas(1112, 834, WEBGL);
	background(100);
	rectMode(CENTER);
}

function draw() {
	shader(theShader);
	background(0);
	theShader.setUniform('u_resolution', [width, height]);
	theShader.setUniform('u_time', millis() / 2000);

	rect(0, 0, width, height);
	// box(250, 250, 250);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (frameCount - lapse > 40){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

// === Tab: vert ===
const vert = `
	#ifdef GL_ES
  	precision highp float;
    precision highp int;
  #endif

	// attribute, in
	attribute vec3 aPosition;
	attribute vec3 aNormal;
	attribute vec2 aTexCoord;
	attribute vec4 aVertexColor;

	// attributes, out
	varying vec3 var_vertPos;
	varying vec3 var_vertNormal;
	varying vec4 var_vertCol;
	varying vec2 var_vertTexCoord;

	// matrices
	uniform mat4 uModelViewMatrix;
	uniform mat4 uProjectionMatrix;
	uniform mat3 uNormalMatrix;

	void main() {
		gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
	}
`;

// === Tab: frag ===
const frag = `
	#ifdef GL_ES
		precision highp float;
	#endif

	uniform vec2 u_resolution;
	uniform float u_time;

	void main(void) {
		vec2 position = -1.0 + 4.0 * gl_FragCoord.xy / u_resolution.xy * cos(5.0) * sin(2.0);

		float color = 0.0;
		color += sin(25.0 + (10.0 + 6.0 + u_time) * cos(u_time * position.x * u_time) + 10.0 + cos(10.0 / 6.0 - 1.0 + position.y) * u_time);
		color += sin(25.0 + (10.0 + 6.0) * sin(u_time * position.x * u_time) - 6.0 + sin(10.0 / 6.0 - 1.0 + position.y) * u_time);
		color += sin(50.0 + (20.0 + 12.0) * cos(u_time / position.x / u_time) - 20.0 + cos(20.0 * 12.0 + 2.0 - position.x / position.y + position.r) * u_time);
		color *= sin(u_time / 10.0) * cos(u_time / 10.0) / 0.5;

		gl_FragColor = vec4( vec3(color, color * 0.5, sin(color + u_time / 3.0) * 0.5), 2.0);
	}
`;

